INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a982a864-41ae-4a58-8d96-e3aa3647cda9', '21feff02-016d-46e2-bb9d-c27495133b1b', '30. óra: Szorzás törttel, a reciprok', 'Tört szorzása törttel, reciprok fogalma.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "48aea50d-99b2-45bc-a637-71cefe70ef07", "text": "Hogyan szorzunk törttel törtet?", "type": "multiple-choice", "options": [{"id": "4a2e80f0-f189-49b9-81cb-d77fb4f6351d", "text": "A számlálót a számlálóval, a nevezőt a nevezővel szorozzuk", "isCorrect": true}, {"id": "118bf638-5a31-4a95-b177-2e4b3d85a6d4", "text": "Közös nevezőre hozzuk őket", "isCorrect": false}, {"id": "ab33276f-6b4e-4fcc-809e-2956aecb941f", "text": "A számlálót a nevezővel szorozzuk", "isCorrect": false}, {"id": "1a879d7c-85d8-4847-ad05-93cdb46e8469", "text": "Keresztbe szorzunk", "isCorrect": false}], "timeLimit": 15}, {"id": "fa759a3c-b29b-4c92-a8af-c4c229619915", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "8fa35579-e85b-44fe-b04d-1b377084e204", "text": "6/15 (azaz 2/5)", "isCorrect": true}, {"id": "09dfde64-72f0-474e-8ee0-3d7e46d448bb", "text": "5/8", "isCorrect": false}, {"id": "14968873-0e4c-4bfb-bfa3-51a3f90375e1", "text": "6/8", "isCorrect": false}, {"id": "36200471-2fca-45e4-9edb-f56ef97ec640", "text": "2/15", "isCorrect": false}], "timeLimit": 15}, {"id": "049a870a-5b22-45f3-90d0-e8295d206cb5", "text": "Mi a 3/4 reciproka?", "type": "multiple-choice", "options": [{"id": "606d5aa9-916f-44ca-b03d-0df56674957c", "text": "4/3", "isCorrect": true}, {"id": "7268976e-342a-4b0b-ad4d-b9ee6cf37c3a", "text": "-3/4", "isCorrect": false}, {"id": "c5d63150-4942-492a-832d-35fea537a0d6", "text": "1/4", "isCorrect": false}, {"id": "3d0512a7-af8a-4097-a251-bbc5b58393a3", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "0651421c-d16d-4833-94e4-2c0238d1c8f0", "text": "Egy szám és a reciproka szorzata mindig 1.", "type": "true-false", "options": [{"id": "6e842432-5267-438a-9592-190186ae1991", "text": "Igaz", "isCorrect": true}, {"id": "3c5d5b7b-413b-465f-871e-ea716b322262", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "038e1398-34f5-4f32-95e4-0279e08834fa", "text": "Mi a 5 egész reciproka?", "type": "multiple-choice", "options": [{"id": "cbd449bb-509a-4225-aa19-af72e011786f", "text": "1/5", "isCorrect": true}, {"id": "9e6a275f-8467-49e6-b160-fabf82de8454", "text": "-5", "isCorrect": false}, {"id": "d6ee8ac2-a597-4573-bc76-af32f71eade6", "text": "5/1", "isCorrect": false}, {"id": "a8bc8f0b-8f41-4960-b0ba-3ae17f485c15", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "4e2219cf-68f7-4be0-85ac-9f708f9493df", "text": "A 0-nak nincs reciproka.", "type": "true-false", "options": [{"id": "9123a032-838c-405a-a0b9-530a0f237288", "text": "Igaz", "isCorrect": true}, {"id": "3d726ab9-b1ad-46e5-af99-b23ac70adfe5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7aa4436f-5264-470b-a0b8-3defb877a07a", "text": "Mennyi 1/2 * 1/3?", "type": "multiple-choice", "options": [{"id": "9f31e6b1-3cff-4ec5-bf35-d0d9026a4f55", "text": "1/6", "isCorrect": true}, {"id": "2559b851-14e6-4c0a-b28e-8f09536efec7", "text": "2/5", "isCorrect": false}, {"id": "e95ea1dd-046c-43ce-980b-cb0b99d32e6f", "text": "1/5", "isCorrect": false}, {"id": "c3c6c64c-4d48-4354-be75-887b13967a32", "text": "2/6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d134ca4a-44ee-4787-91e9-834e4696d1cd', '21feff02-016d-46e2-bb9d-c27495133b1b', '31. óra: A törtek szorzását alkalmazó feladatok megoldása', 'Törtrész kiszámítása és szöveges feladatok megoldása szorzással.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "18f626cc-e035-4f56-b82f-247f292918a1", "text": "Mennyi 60-nak a 3/4 része? (60 * 3/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "0a77936e-834d-4fe9-8d33-54333229c902", "text": "Mennyi 100-nak az 1/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "39dbb6f8-c3c2-4d8a-aaca-439cbd10fb99", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szeletet ettek meg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "734ded47-d3ec-4897-aca7-79490714deb0", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szelet maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "4fd08e01-5d1b-499b-88fd-680223334ff2", "text": "Egy szám törtrészének kiszámításához a számot megszorozzuk a törttel.", "type": "true-false", "options": [{"id": "ed914c8f-e569-4007-9cc7-a4dc8640c6df", "text": "Igaz", "isCorrect": true}, {"id": "205cdea6-ec5b-4be8-a85a-cfa083bafc16", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "399a17f1-bacf-419c-805d-ab54126d712b", "text": "Mennyi 50-nek a 2/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "5c7946ca-4d5c-4f0d-b120-93fa6a53cae4", "text": "Mennyi 1/2 óra percekben? (60 * 1/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5124739c-dab4-4adb-98dd-0268d58f2978', '21feff02-016d-46e2-bb9d-c27495133b1b', '32. óra: Osztás törttel', 'Törttel való osztás szabálya: szorzás a reciprokával.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "f8e4b860-b80e-403a-bca8-86a3e846b6be", "text": "Hogyan osztunk törttel?", "type": "multiple-choice", "options": [{"id": "6679c622-3d0b-4763-a423-8ba549f7fe6f", "text": "Az osztandót megszorozzuk az osztó reciprokával", "isCorrect": true}, {"id": "d8a966ac-2153-41da-b0a9-9baac2998240", "text": "Az osztandót elosztjuk a nevezővel", "isCorrect": false}, {"id": "03557efe-0779-4619-868d-a538fe35121c", "text": "Mindig 1-et kapunk", "isCorrect": false}, {"id": "008c9e6c-d7f7-4103-b344-b0f3bae1a6e7", "text": "A számlálókat elosztjuk egymással", "isCorrect": false}], "timeLimit": 15}, {"id": "42c6f64d-35c4-4adc-a86b-367958dcd5a4", "text": "Mennyi 2/3 : 4/5? (2/3 * 5/4)", "type": "multiple-choice", "options": [{"id": "a72be38a-41fa-49d8-adb8-288349122f62", "text": "10/12 (azaz 5/6)", "isCorrect": true}, {"id": "13826f70-fbbd-4c17-9770-f2968e83c6e3", "text": "8/15", "isCorrect": false}, {"id": "0fd11ec9-63d4-488b-8890-95e0c521300f", "text": "6/8", "isCorrect": false}, {"id": "116ae378-996d-4d17-9f31-0a57de4e690e", "text": "15/8", "isCorrect": false}], "timeLimit": 15}, {"id": "aacf15d9-3ea9-40da-a8a4-a378d7b34316", "text": "Mennyi 1/2 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "a042670f-adce-4496-ab64-76b614ada4bf", "text": "Ha egy számot 1/2-del osztunk, az eredmény megegyezik a szám 2-vel való szorzatával.", "type": "true-false", "options": [{"id": "51b7cd12-5eed-436b-aa47-e8d95d33f71a", "text": "Igaz ( : 1/2 = * 2)", "isCorrect": true}, {"id": "d2fce4e5-488f-4aa4-aac4-d624db0fc875", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6702fe19-8545-4d19-8a96-1584a9d32114", "text": "Mennyi 6 : 1/3? (6 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "9d8f2c31-9f09-4340-b025-d8886d3caf5b", "text": "Törttel való osztáskor az osztandó nem változik, csak az osztót fordítjuk meg.", "type": "true-false", "options": [{"id": "1745ef35-abd6-407c-8a21-f5424896fd27", "text": "Igaz", "isCorrect": true}, {"id": "7e751bca-7a5a-4004-bce6-d9d0c10b77d4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "35dfbb2e-67a0-456a-9d6c-f8f54200a094", "text": "Mennyi 3/4 : 3/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('46e9b75b-6d8c-4582-8a22-09ad5ee0726d', '21feff02-016d-46e2-bb9d-c27495133b1b', '33. óra: Hétköznapi problémák megoldása törtek osztásának felhasználásával', 'Szöveges feladatok mérésekkel, átdarabolásokkal, törtek osztásával.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "86f8661f-f429-48ab-991a-33c5490d5406", "text": "Hány 1/4 literes pohár tölthető meg 3 liter almaléből? (3 : 1/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "11a027fc-cb2a-42a8-b8aa-8ba4baee3a70", "text": "Hány 1/2 kg-os csomag képezhető 5 kg cukorból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "42a2e278-6cf1-4ce5-a20b-974ebaf04b23", "text": "Egy 6 méteres szalagból 3/4 méteres darabokat vágunk. Hány darabot kapunk? (6 : 3/4 = 6 * 4/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "a4075ac2-356f-4221-9a20-c9395d469d21", "text": "Törtek osztásakor az eredmény lehet nagyobb az eredeti osztandónál, ha az osztó 1-nél kisebb tört.", "type": "true-false", "options": [{"id": "de1e4011-4f22-4c68-a320-95552977e2c5", "text": "Igaz", "isCorrect": true}, {"id": "8492f05a-54c4-4165-90c1-61699c6c06cf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7a40691f-5f12-400c-bcda-5923e71e9481", "text": "Hány 1/5 méteres darab vágható ki 2 méter anyagból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "ad4d2a8f-27b1-444b-8dc4-53341ec532bb", "text": "A szöveges feladatoknál az adatok lejegyzése és a mértékegységek egyeztetése elengedhetetlen.", "type": "true-false", "options": [{"id": "5888a8f6-9eb4-4b6f-a7aa-86ffa70b66c6", "text": "Igaz", "isCorrect": true}, {"id": "d277fefb-ed0e-4f71-83d2-0f5cd0cd1304", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6441f937-6f9f-4ff8-a93f-70c2fa2145e5", "text": "Mennyi 4 : 2/3? (4 * 3/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('41bc692d-04e2-44d7-9813-762c3d82907c', '21feff02-016d-46e2-bb9d-c27495133b1b', '34. óra: Gyakorlóóra', 'A törtek szorzásának és osztásának rögzítése, feladatok gyakorlása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "d52af73c-3355-4b1a-b539-9e928ca51fba", "text": "Mennyi 3/5 * 5/3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "d94ac14e-0b73-4b36-96f8-0a4ceb9458d5", "text": "Mennyi 4/7 : 2/7? (4/7 * 7/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "2d722c40-1ea8-41b6-a045-3087d62e4f00", "text": "Melyik állítás igaz?", "type": "multiple-choice", "options": [{"id": "6077c84d-c2eb-41d6-ab7a-20f8b80f5891", "text": "Két 1-nél kisebb pozitív tört szorzata kisebb mindkét tényezőnél", "isCorrect": true}, {"id": "961b8bfc-13ff-493a-9352-0c63bb8877d5", "text": "A szorzat mindig nagyobb a tényezőknél", "isCorrect": false}, {"id": "95ab6c6c-2a5e-4d33-8aad-8184831f8146", "text": "Az osztás mindig kisebb számot ad", "isCorrect": false}, {"id": "b2d1081e-c654-4318-91f7-fdcc015ba794", "text": "Nincs reciproka a 4/5-nek", "isCorrect": false}], "timeLimit": 15}, {"id": "dec7e324-b707-4207-ab61-fe30058d0886", "text": "Mennyi 5/6 * 12? (5 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "a1a68e6e-d871-4ee9-bca6-5f9698e5cc02", "text": "A 2/3 osztva 1/3-dal 2-t ad.", "type": "true-false", "options": [{"id": "ca6f42af-c1a6-4643-9ffa-abd182f5f7eb", "text": "Igaz", "isCorrect": true}, {"id": "69242a37-b54c-4f0f-92dc-6937e553b9be", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a8ceeba0-ab50-45bf-9e9c-4e7278f3830c", "text": "Mennyi 3/8 : 3/8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "b99cb958-dc96-436e-899f-b3a39087ff4f", "text": "Mennyi 1/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "56c96bdd-1d66-49e9-abdc-2cfe734406da", "text": "1/5", "isCorrect": true}, {"id": "145349c2-ae2f-4036-a18d-bfc7de4f3e67", "text": "4/20", "isCorrect": false}, {"id": "b4aa8cd5-39d8-4667-8323-78f48ae085bd", "text": "1/20", "isCorrect": false}, {"id": "c2ff6bb9-dedb-4712-b658-8ea54d85c731", "text": "4/9", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('826d64cf-a8fe-4552-8f4f-7ad7f4de1fa2', '21feff02-016d-46e2-bb9d-c27495133b1b', '35. óra: Számonkérés', 'Számonkérés a közönséges törtek műveleteiből (10 kérdés).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "d0458f0c-831b-426a-ac3d-d12ff4ac923a", "text": "1. Mennyi 2/5 + 1/5?", "type": "multiple-choice", "options": [{"id": "86dfc106-86df-4c44-bf88-b18f94e478ae", "text": "3/5", "isCorrect": true}, {"id": "e0f0d20c-5967-405a-a4a7-d16b4d272b9b", "text": "3/10", "isCorrect": false}, {"id": "3af049ae-99bc-4652-bf26-77ed982301a6", "text": "2/10", "isCorrect": false}, {"id": "9df336bf-866e-42f0-bc0e-93c6e66337fa", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "39929480-b5bf-498d-9328-9f1774238278", "text": "2. Mennyi 3/4 - 1/2? (3/4 - 2/4)", "type": "multiple-choice", "options": [{"id": "f6fc83e0-fcb8-4a76-9310-20bd4e3ae74e", "text": "1/4", "isCorrect": true}, {"id": "189d3939-3cb3-499a-b3ed-052c5cf1082c", "text": "2/2", "isCorrect": false}, {"id": "d58414b5-b37e-4daf-8eba-ddd5599e5e66", "text": "1/2", "isCorrect": false}, {"id": "2ca48939-1bdc-4e76-b695-b4d09b8b84a1", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "9ac41eb8-2c2a-424c-95e3-13277028f4f7", "text": "3. Mennyi 2/3 * 3/4?", "type": "multiple-choice", "options": [{"id": "e5be44c4-e00f-4e7b-ae59-67f9ee118e0c", "text": "6/12 (azaz 1/2)", "isCorrect": true}, {"id": "deaae9c8-cf92-4ab3-b7a7-06c1e726b6db", "text": "5/7", "isCorrect": false}, {"id": "3ffbb81e-defd-43e0-a5bc-14a94599c9c6", "text": "6/7", "isCorrect": false}, {"id": "a4ff64e4-9460-47a5-8f65-7bc03dd5d225", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "cfa2d2af-c872-479d-abba-0f33dc9833f1", "text": "4. Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "2b920843-d418-40c7-923e-7dff8524b5a1", "text": "5. Mi a 7/8 reciproka?", "type": "multiple-choice", "options": [{"id": "b3453963-e8fb-4288-8eff-06de90acf1d5", "text": "8/7", "isCorrect": true}, {"id": "1ee0ac7e-fe2a-4856-a4b7-df76d4a82a0c", "text": "-7/8", "isCorrect": false}, {"id": "77e7729b-6b93-422a-9042-188be1936cfd", "text": "1/7", "isCorrect": false}, {"id": "d4d57e89-56d2-4d32-b3e9-33afe32fd94e", "text": "7/8", "isCorrect": false}], "timeLimit": 15}, {"id": "1c869d42-1600-445d-b900-74415f5645ad", "text": "6. Mennyi 40-nek a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "903e1660-344b-40d9-8060-d07ece92e1b3", "text": "7. Egy szám és reciproka szorzata 1.", "type": "true-false", "options": [{"id": "ba876901-e996-41cb-b722-abef505e2963", "text": "Igaz", "isCorrect": true}, {"id": "0f49a9a7-1341-437c-9c9e-a07b49bf6f7f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a299d430-4c0b-48fd-a729-91268f48e4c2", "text": "8. Mennyi 5 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "e2b0bad1-d93f-40a3-9c6b-1bebbe3be28e", "text": "9. A törtek szorzásakor a számlálót a számlálóval, a nevezőt a nevezővel szorozzuk.", "type": "true-false", "options": [{"id": "7bd558b3-7210-4590-9878-edeca2688ba8", "text": "Igaz", "isCorrect": true}, {"id": "67aa0541-f51e-4438-86a5-5fb7ba260ec0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "aa6b01d0-de14-426c-951c-f5b2cee5b31e", "text": "10. Hány negyedből áll 3 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4ed54d35-a3eb-48a9-acc1-c7867e0f9015', '21feff02-016d-46e2-bb9d-c27495133b1b', '36. óra: Matematikai játékok', 'Matematikai társasjátékok, stratégiák törtekkel, csoport- és páros munka.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "6ba105c5-6b8a-409d-aa7c-eaecf49865b2", "text": "Melyik állítás igaz a matematikai társasjátékokról?", "type": "multiple-choice", "options": [{"id": "ddc2204b-3922-4774-8823-cb677d2ab017", "text": "Fejlesztik a számolási gyorsaságot és a logikai stratégiát", "isCorrect": true}, {"id": "cf8c2456-14e6-4200-a7d5-f98d06bf1e52", "text": "Nincs közük a matematikához", "isCorrect": false}, {"id": "f095af87-d3a5-443b-a376-f052f349ba43", "text": "Kizárólag szerencse kell hozzájuk", "isCorrect": false}, {"id": "d8014217-bd95-4ab2-9bab-6c2907ef729b", "text": "Tiltható az együttműködés", "isCorrect": false}], "timeLimit": 15}, {"id": "b8e00c82-0325-4fc5-bd42-c7b6293557a0", "text": "A tört domino játékban az egyenlő értékű törteket illesztjük össze.", "type": "true-false", "options": [{"id": "3737b821-637e-4f1f-8faa-8c294019f558", "text": "Igaz", "isCorrect": true}, {"id": "e4639d9e-f1f2-4787-92c2-ea34b20f9cb3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3c583910-4861-4dfb-9c02-a4e5f14bf43f", "text": "Melyik tört felel meg a 0,5 tizedes törtnek?", "type": "multiple-choice", "options": [{"id": "39c8e1c0-f446-4fcb-bc6f-8568dbccbc9b", "text": "1/2", "isCorrect": true}, {"id": "d903f4ca-8509-434e-bc99-b4adb505f074", "text": "1/5", "isCorrect": false}, {"id": "f6e7c27c-ac76-4d4c-a32b-067427d24809", "text": "2/5", "isCorrect": false}, {"id": "72bc6fa5-0fea-4572-a31a-cbb547677a70", "text": "5/2", "isCorrect": false}], "timeLimit": 15}, {"id": "7803cea5-3029-4f7d-bd10-2732f2f54fc1", "text": "Melyik tört felel meg a 0,25-nek?", "type": "multiple-choice", "options": [{"id": "372330ee-ccda-49cb-be9c-80b522663b5c", "text": "1/4", "isCorrect": true}, {"id": "ac1fe40d-86d6-4c4f-bc7e-eacb3980e008", "text": "1/2", "isCorrect": false}, {"id": "d3f73d2d-3e59-423d-93a3-39c1b553f82e", "text": "2/5", "isCorrect": false}, {"id": "86e870a1-ba3d-438d-a396-79b3fbe9d395", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "c55ffbb1-b5e2-4eaa-ba6c-1baf204cfa5a", "text": "A 3/4 tizedes tört alakja 0,75.", "type": "true-false", "options": [{"id": "b2103fc9-f7da-4596-b813-65d97ed82420", "text": "Igaz", "isCorrect": true}, {"id": "f5ad74b5-71c0-43d2-929a-e92f18abd478", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4e0418f7-bc38-4447-bd56-d971e2a23ccd", "text": "Mennyi 0,2 közönséges tört alakban legegyszerűbb formában?", "type": "multiple-choice", "options": [{"id": "71193562-4d48-43d8-a35d-885f262d21a1", "text": "1/5", "isCorrect": true}, {"id": "8f60aeb4-ee63-4656-af38-57d6f85f7f12", "text": "2/10", "isCorrect": false}, {"id": "299176c6-4b7b-498f-977c-51c136599b47", "text": "1/2", "isCorrect": false}, {"id": "cfc5b1f3-8398-4b11-affb-118ccff73b33", "text": "2/5", "isCorrect": false}], "timeLimit": 15}, {"id": "7957696e-9a66-4ec7-afd0-10eee22a5ac3", "text": "A tört-bingó játékban a válaszok gyors és pontos kiszámítása a nyerő stratégia.", "type": "true-false", "options": [{"id": "4ef7f1ff-89e7-4ad1-bbbc-798456cfcdc4", "text": "Igaz", "isCorrect": true}, {"id": "a028cdde-02d8-464a-9a39-45dbd92f682c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('878105d9-dffc-4198-b888-8007579f0f2e', '21feff02-016d-46e2-bb9d-c27495133b1b', '37. óra: Mit tanultunk a tizedes törtekről?', 'Tizedes törtek helyi értékei, összeadása és kivonása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "6e3257ec-79bc-4ca3-b33b-313d3820ed7a", "text": "Mi a tizedesvessző utáni első helyi érték neve?", "type": "multiple-choice", "options": [{"id": "7005e907-0d85-4712-bbf9-67be782747df", "text": "Tizedek", "isCorrect": true}, {"id": "3ba8baa3-9500-4474-9714-59b7e26b1623", "text": "Századok", "isCorrect": false}, {"id": "179ffcbd-e2ad-4223-8924-c0eae8c18957", "text": "Ezredeket", "isCorrect": false}, {"id": "698d0a7f-ee68-4606-9c0f-ddc98c6da05b", "text": "Egyesek", "isCorrect": false}], "timeLimit": 15}, {"id": "326ac3a3-c0a1-45fd-aaa7-6d7aee149185", "text": "Mi a tizedesvessző utáni második helyi érték neve?", "type": "multiple-choice", "options": [{"id": "67d37015-97d2-4841-83e2-62a276b85a94", "text": "Századok", "isCorrect": true}, {"id": "b0b0b2d2-04f3-4386-85ee-2fc11bf8aad3", "text": "Tizedek", "isCorrect": false}, {"id": "0658fc40-3ae5-41e2-9ed3-f13ec55ed909", "text": "Ezredek", "isCorrect": false}, {"id": "961f7c12-6c8c-452b-b042-402abdb75c07", "text": "Tízesek", "isCorrect": false}], "timeLimit": 15}, {"id": "ffc25039-0bbe-472a-bee0-612f3cd1baa5", "text": "Mennyi 3,45 + 2,13?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5.58"}, {"id": "ab2baad8-dac8-4f89-8a7a-999f59a39c62", "text": "Mennyi 7,8 - 3,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.3"}, {"id": "4202609c-9df4-4934-a8ca-cbb09ea0a76e", "text": "Tizedes törtek írásbeli összeadásakor a tizedesvesszőknek egymás alá kell kerülniük.", "type": "true-false", "options": [{"id": "9fe3f567-79d1-4234-8f2c-727200b01c4f", "text": "Igaz", "isCorrect": true}, {"id": "626d00ec-728c-44ef-a0fa-2977c540b25c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "827dc1e9-f983-4746-b063-99b5257f30df", "text": "Mennyi 5,6 + 4,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "c6036c4b-a448-4682-85e3-1091971668b2", "text": "Melyik szám nagyobb: 4,05 vagy 4,5?", "type": "multiple-choice", "options": [{"id": "fe5e6fed-8cd0-4cbc-b774-3f909900ca34", "text": "4,5 (mert 4,5 = 4,50)", "isCorrect": true}, {"id": "8446196d-6888-43c0-8f83-4a8fe4edb338", "text": "4,05", "isCorrect": false}, {"id": "2300ec05-02f6-40d9-a6c9-e70ed0a99b41", "text": "Egyenlőek", "isCorrect": false}, {"id": "ca311deb-870e-4bd4-a609-f56d5183296c", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8ac22f01-d8df-4117-b2ee-5bab6b453224', '21feff02-016d-46e2-bb9d-c27495133b1b', '38. óra: Szorzás tizedes törttel', 'Tizedes tört szorzása egész számmal és tizedes törttel, vesszőhely meghatározása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "9eb15d1d-4dab-4031-a13f-e2c980ca94d6", "text": "Hogyan határozzuk meg a tizedesjegyek számát két tizedes tört szorzatában?", "type": "multiple-choice", "options": [{"id": "2e1c41d8-23dc-479f-a3f5-de0ff20a47bb", "text": "A tényezők tizedesjegyeinek számát összeadjuk", "isCorrect": true}, {"id": "d897fce9-5b46-4c40-86c4-07952f2c2f5d", "text": "A nagyobbik tényező tizedesjegyeit vesszük", "isCorrect": false}, {"id": "6ca26b39-8858-4392-9e88-9597f114756f", "text": "Mindig 1 tizedesjegy lesz", "isCorrect": false}, {"id": "5c03fcd5-f4e7-4ed6-a9ab-58ac99b35b73", "text": "Nem lesz tizedesjegy", "isCorrect": false}], "timeLimit": 15}, {"id": "d81f0439-c7cb-4ffa-bcde-1349151bd9e2", "text": "Mennyi 0,3 * 0,2? (3*2 = 6, 2 tizedesjegy)", "type": "multiple-choice", "options": [{"id": "9c28fd89-c05e-4ac1-83a2-e6da1c0a7077", "text": "0,06", "isCorrect": true}, {"id": "9144b011-a3b4-489c-b0f6-c03e1ff79654", "text": "0,6", "isCorrect": false}, {"id": "3a316fda-57c6-44e7-8a99-c89bf83ef5ca", "text": "6,0", "isCorrect": false}, {"id": "6e8f8fde-29e4-4a95-96d6-a03a628135e5", "text": "0,006", "isCorrect": false}], "timeLimit": 15}, {"id": "abd7c35c-3f27-488a-a2b9-60e65865e0f3", "text": "Mennyi 2,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "39541bdf-9782-4c6e-b50f-f9a659f7a8d9", "text": "Mennyi 1,2 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "e56a4e3c-4551-4c25-b40a-2348d41c29a5", "text": "Ha egy tizedes törtet 10-zel szorzunk, a tizedesvessző egy hellyel jobbra lép.", "type": "true-false", "options": [{"id": "cf90131e-603c-441c-8d80-8add48f0437f", "text": "Igaz", "isCorrect": true}, {"id": "8a606a23-5c7e-4fcd-afc8-122be1da2bce", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "805e0a63-acac-4934-b5e5-65e24034ba2a", "text": "Mennyi 3,45 * 100?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "345"}, {"id": "78c0cd2b-5ddb-4b66-a8cc-466ed04a0c2b", "text": "Mennyi 0,1 * 0,1?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.01"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2c505da8-c03a-45bb-b96b-72d6c46910f8', '21feff02-016d-46e2-bb9d-c27495133b1b', '39. óra: Osztás tizedes törttel', 'Tizedes törttel való osztás szabálya, osztó egész számmá alakítása (bővítés 10-zel, 100-zal).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "77e1fd01-cdb3-46f4-9031-f22d421c56e8", "text": "Mit teszünk tizedes törttel való osztáskor először?", "type": "multiple-choice", "options": [{"id": "111873bc-3e2b-41f5-a83d-e3cf4d61b907", "text": "Az osztandót és az osztót is megszorozzuk 10-zel/100-zal, hogy az osztó egész szám legyen", "isCorrect": true}, {"id": "a474c1e5-f0cb-4e4b-96d1-992f79b8b891", "text": "Elhagyjuk a tizedesvesszőt az osztandóból", "isCorrect": false}, {"id": "12c8fd98-bac0-421b-8c7a-756034ffdcf9", "text": "Kivonjuk az osztót az osztandóból", "isCorrect": false}, {"id": "a37f2341-36a3-4e89-9342-092daa9fe468", "text": "Csak az osztót szorozzuk meg", "isCorrect": false}], "timeLimit": 15}, {"id": "56d31c82-8925-4643-8805-a03ff5a25da5", "text": "Mennyi 2,4 : 0,6? (24 : 6)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "4937b823-dc96-490b-beea-8b87ac9a50a4", "text": "Mennyi 1,5 : 0,3? (15 : 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "c1aba5b3-4ed8-469c-9c21-36b6426c78a4", "text": "Ha egy tizedes törtet 10-zel osztunk, a tizedesvessző 1 hellyel balra lép.", "type": "true-false", "options": [{"id": "9a60fd09-7bc5-4633-9b7b-0323fc9b4735", "text": "Igaz", "isCorrect": true}, {"id": "e76fd779-c1c6-49bd-94d7-032a8927cd95", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "37056007-9ca0-4826-b54e-236f3010930d", "text": "Mennyi 45,6 : 10?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.56"}, {"id": "36d25dbe-88df-44c0-b9f7-e1285d95cb90", "text": "Mennyi 3,6 : 0,1? (36 : 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "da3758c6-2644-4c5f-81e9-d814dad48c90", "text": "A tizedes törttel való osztást ellenőrizhetjük szorzással.", "type": "true-false", "options": [{"id": "a73da70f-cb09-458f-91fd-33f19c517eb8", "text": "Igaz", "isCorrect": true}, {"id": "67739702-ea20-4267-9971-4f69177b5198", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());